# Battery: per block, boolean features tested against label across all demos.
feats={}
def feats_of(b,bbset):
    s={}
    # same row / same col partner
    s['same_row'] = any(a[0]==b[0] for a in bbset if a!=b)
    s['same_col'] = any(a[1]==b[1] for a in bbset if a!=b)
    s['diag_opp'] = any(a[0]-b[0]==-(b[1]-a[1]) and abs(a[0]-b[0])<=4 for a in bbset if a!=b)
    s['diag_main'] = any(a[0]-b[0]==a[1]-b[1] and abs(a[0]-b[0])<=4 for a in bbset if a!=b)
    # within row, is there a block further right / further left?
    s['left_in_row'] = any(a[1]<b[1] for a in bbset if a[0]==b[0])
    s['right_in_row'] = any(a[1]>b[1] for a in bbset if a[0]==b[0])
    s['above_in_col'] = any(a[0]<b[0] for a in bbset if a[1]==b[1])
    s['below_in_col'] = any(a[0]>b[0] for a in bbset if a[1]==b[1])
    return s
